(1483, '3831', 'INMUNOGLOBULINA HUMANA HIPERINMUNE ANTITETANICA', 'SOLUCION INYECTABLE', '250 UI/3 ML O 1 ML', 'FRASCO AMPULA CON 3 ML O AMPOLLETA CON 1 ML', 'PRIMER NIVEL', 'VACUNAS, TOXOIDES, INMUNOGLOBULINAS, ANTITOXINAS', 'ANTICUERPOS CON ACTIVIDAD ANTITETÁNICA QUE PROPORCIONA INMUNIDAD PASIVA CONTRA EL TÉTANOS.', 'C', 'FIEBRE MODERADA, DOLOR LOCAL, ANAFILAXIA.', 'CONTRAINDICACIONES: HIPERSENSIBILIDAD AL FÁRMACO. NO SUMINISTRAR A PERSONAS CON TROMBOCITOPENIA GRAVE U OTRO TRASTORNO DE LA COAGULACIÓN, NO ADMINISTRAR POR VÍA INTRAVENOSA.\r\nPRECAUCIONES: UTILIZARLA SÓLO SI LA HERIDA TIENE MÁS DE 24 HORAS.', 'NINGUNA DE IMPORTANCIA CLÍNICA.', 'INMUNIZACIÓN PASIVA CONTRA LA TOXINA TETÁNICA.\r\n\r\nTÉTANOS.', 'INTRAMUSCULAR.\r\n\r\nADULTOS Y NINOS:\r\n\r\nPROFILAXIS, APLICACION DE 500 UI DE INMUNOGLOBULINA, EN NINOS DE APLICAN 250 UI Y TOXOIDE TETANICO (0.5ML)\r\n\r\nCURATIVA, DE 5 000 A 6 000 U.I. \r\nEL PRIMER DIA, DOSIS  POSTERIORES SE APLICARAN EN LOS DIAS SUBSECUENTES D???\0\0\0\0??????\0?\0??\0??', 'INTRAMUSCULAR', 'CADA FRASCO ÁMPULA O AMPOLLETA CONTIENE:\r\nINMUNOGLOBULINA HUMANA HIPERINMUNE\r\nANTITETÁNICA 	250 UI', 'ENVASE CON UN FRASCO ÁMPULA 3 ML O UNA AMPOLLETA CON UN ML', 0, 20, 0, NULL, NULL),
