--
-- Estructura de tabla para la tabla `venta_conceptos`
--

CREATE TABLE `venta_conceptos` (
`id_vc` bigint(20) unsigned NOT NULL,
  `id_personal_medico_vc` int(10) unsigned NOT NULL COMMENT 'El id del personal q va atender el concepto',
  `precio_vc` float(8,2) unsigned NOT NULL DEFAULT '0.00' COMMENT 'El precionormal del concepto en su tabla',
  `id_convenio_vc` int(10) unsigned NOT NULL DEFAULT '0' COMMENT 'el id del convenio q utilizamos para el concepto',
  `id_paciente_vc` bigint(20) unsigned NOT NULL,
  `id_usuario_vc` int(10) unsigned NOT NULL COMMENT 'id del usuario que guarda el concepto',
  `fecha_venta_vc` datetime NOT NULL,
  `estatus_vc` tinyint(3) unsigned NOT NULL DEFAULT '1',
  `urgente_vc` tinyint(3) unsigned DEFAULT '0',
  `usuarioEdo1_e` int(10) unsigned DEFAULT NULL,
  `fechaEdo1_e` datetime DEFAULT NULL,
  `usuarioEdo2_e` int(10) unsigned DEFAULT NULL,
  `fechaEdo2_e` datetime DEFAULT NULL,
  `usuarioEdo3_e` int(10) unsigned DEFAULT NULL,
  `fechaEdo3_e` datetime DEFAULT NULL,
  `usuarioEdo4_e` int(10) unsigned DEFAULT NULL,
  `fechaEdo4_e` datetime DEFAULT NULL,
  `usuarioEdo5_e` varchar(10) COLLATE latin1_spanish_ci DEFAULT NULL,
  `fechaEdo5_e` datetime DEFAULT NULL,
  `usuarioEdo6_e` varchar(10) COLLATE latin1_spanish_ci DEFAULT NULL,
  `fechaEdo6_e` datetime DEFAULT NULL,
  `id_concepto_es` int(10) unsigned NOT NULL COMMENT 'En el caso de ser un estudioo algun servicio, guardamos su id, en caso de consulta no es necesario',
  `referencia_vc` varchar(20) COLLATE latin1_spanish_ci DEFAULT NULL,
  `interpretacion_vc` text COLLATE latin1_spanish_ci,
  `nota_interpretacion` text COLLATE latin1_spanish_ci,
  `otras_indicaciones` text COLLATE latin1_spanish_ci,
  `nota_receta` text COLLATE latin1_spanish_ci,
  `contador_vc` int(10) unsigned DEFAULT NULL,
  `nota_radiologo_vc` text COLLATE latin1_spanish_ci,
  `birad_vc` tinyint(3) unsigned DEFAULT NULL COMMENT 'En las mastografias debe llevar BIRAD',
  `no_temp_vc` varchar(100) COLLATE latin1_spanish_ci DEFAULT NULL,
  `motivo_visita_vc` text COLLATE latin1_spanish_ci,
  `temporal_vc` tinyint(3) unsigned NOT NULL DEFAULT '1' COMMENT '1 Si es un registro temporal, cuando aún no se guarda la orden de venta',
  `observaciones_vc` text COLLATE latin1_spanish_ci,
  `id_signosv_vc` bigint(20) unsigned DEFAULT NULL,
  `id_conceptos_beneficios` bigint(20) unsigned NOT NULL COMMENT 'el id de la tabla de cenceptos_beneficios, para asi saber cual concepto de los beneficios ponerlo como usado en la disponibilidad de los conceptos de los beneficios del paciente',
  `es_beneficio_vc` tinyint(3) unsigned DEFAULT '0',
  `id_anesteciologo_vc` int(10) unsigned DEFAULT NULL,
  `id_radiologo_externo` int(10) unsigned NOT NULL DEFAULT '0',
  `id_pacs` varchar(15) COLLATE latin1_spanish_ci DEFAULT NULL,
  `usuario_transfiere_vc` int(10) unsigned DEFAULT NULL,
  `fecha_transfiere_vc` datetime DEFAULT NULL,
  `salvado_vc` tinyint(1) unsigned NOT NULL DEFAULT '0'
) ENGINE=InnoDB AUTO_INCREMENT=63144 DEFAULT CHARSET=latin1 COLLATE=latin1_spanish_ci;

